starterCodeJson.code:
#!/usr/bin/env bash
# Sau buoc, DUNG thu tu, va DUNG LAI o buoc hong dau tien.
# Hai buoc dau khong can thong tin dang nhap — do la ly do chung dung truoc.
set -uo pipefail

DEST=${1:?usage: triage.sh [user@]HOST [PORT]}
PORT=${2:-22}
HOSTONLY=${DEST#*@}
case "$DEST" in *@*) USERNAME=${DEST%@*} ;; *) USERNAME=$(id -un) ;; esac

fail() { echo "FAIL $1 $2"; echo "FIX: $3"; exit "$1"; }

# TODO 1: mo TCP, han 5 giay. Phan biet refused (nhanh) va timeout (cham).

# TODO 2: doc banner tu CHINH socket vua mo. Khong bat dau bang SSH- -> fail 2.

# TODO 3-6: chay ssh -v MOT LAN, giu lai vet chay, roi xet:
#   - khong co dong "Offering public key"     -> fail 3 (client khong co khoa nao)
#   - co Offering ma khong co "Server accepts" -> fail 4 (may chu nhin roi noi khong)
#   - tu 3 dong Offering tro len               -> canh bao MaxAuthTries
#   - co "Server accepts key"                  -> OK, thoat 0

